{'content': '// Print-in-Place Planetary Gearbox
// Single stage with 3 planet gears
// Designed for PETG with 0.4mm nozzle, 0.1mm layer height

$fn = 60;

// Clearance for print-in-place (critical for PETG)
clearance = 0.3; // horizontal clearance
z_clearance = 0.2; // vertical clearance

// Gear parameters
sun_teeth = 12;
planet_teeth = 12;
ring_teeth = sun_teeth + 2 * planet_teeth; // = 36
module_pitch = 2.0; // module (mm per tooth)

// Derived dimensions
sun_pitch_dia = sun_teeth * module_pitch;
planet_pitch_dia = planet_teeth * module_pitch;
ring_pitch_dia = ring_teeth * module_pitch;

// Gear geometry
gear_thickness = 8;
tooth_height = 2.25 * module_pitch;
base_height = 2;
carrier_height = gear_thickness + base_height + z_clearance;

// Planet carrier parameters
num_planets = 3;
planet_orbit_radius = (sun_pitch_dia + planet_pitch_dia) / 2;

// Ring gear dimensions
ring_outer_radius = ring_pitch_dia/2 + tooth_height + 4;
ring_height = gear_thickness + base_height + carrier_height + 3;

// Involute gear tooth profile (simplified)
module gear(teeth, thickness, bore_dia, clearance_adj=0) {
    pitch_dia = teeth * module_pitch;
    outer_dia = pitch_dia + 2 * tooth_height - clearance_adj;
    root_dia = pitch_dia - 2 * tooth_height + clearance_adj;

    difference() {
        cylinder(h=thickness, d=outer_dia, center=false);

        // Cut teeth (simplified approach)
        for (i = [0:teeth-1]) {
            rotate([0, 0, i * 360/teeth])
            translate([pitch_dia/2, 0, -0.1])
            cylinder(h=thickness+0.2, d=tooth_height*0.8, center=false);
        }

        // Bore
        translate([0, 0, -0.1])
        cylinder(h=thickness+0.2, d=bore_dia, center=false);
    }
}

// Better involute gear profile
module involute_gear(teeth, thickness, bore_dia, clearance_adj=0, is_internal=false) {
    pitch_dia = teeth * module_pitch;
    addendum = module_pitch;
    dedendum = 1.25 * module_pitch;

    if (is_internal) {
        // Internal ring gear
        outer_dia = pitch_dia + 2 * dedendum;
        inner_dia = pitch_dia - 2 * addendum + clearance_adj;

        difference() {
            cylinder(h=thickness, d=outer_dia, center=false);

            // Internal teeth profile
            translate([0, 0, -0.1])
            union() {
                cylinder(h=thickness+0.2, d=inner_dia, center=false);

                // Tooth spaces
                for (i = [0:teeth-1]) {
                    rotate([0, 0, i * 360/teeth + 360/(2*teeth)])
                    translate([pitch_dia/2, 0, 0])
                    cylinder(h=thickness+0.2, d=addendum*1.5, center=false, $fn=20);
                }
            }
        }
    } else {
        // External gear
        outer_dia = pitch_dia + 2 * addendum - clearance_adj;
        root_dia = pitch_dia - 2 * dedendum + clearance_adj;

        difference() {
            union() {
                cylinder(h=thickness, d=root_dia, center=false);

                // Teeth
                for (i = [0:teeth-1]) {
                    rotate([0, 0, i * 360/teeth])
                    translate([pitch_dia/2, 0, 0])
                    cylinder(h=thickness, d1=addendum*1.8, d2=addendum*1.4, center=false, $fn=20);
                }
            }

            // Bore
            translate([0, 0, -0.1])
            cylinder(h=thickness+0.2, d=bore_dia, center=false);
        }
    }
}

// Sun gear (rotatable, driven)
module sun_gear() {
    sun_bore = 6;
    sun_shaft_height = ring_height - 1;

    translate([0, 0, base_height + z_clearance]) {
        involute_gear(sun_teeth, gear_thickness, sun_bore, clearance);

        // Drive shaft extending up
        translate([0, 0, gear_thickness])
        cylinder(h=sun_shaft_height - gear_thickness - base_height, d=sun_bore - 0.5, center=false);
    }
}

// Planet gear
module planet_gear() {
    planet_bore = 4;
    involute_gear(planet_teeth, gear_thickness, planet_bore, clearance);
}

// Planet carrier (rotatable output)
module planet_carrier() {
    carrier_outer_dia = planet_orbit_radius * 2 - planet_pitch_dia/2 - 2;
    carrier_thickness = 3;
    pin_height = gear_thickness - z_clearance;
    pin_dia = 4 - clearance * 2;

    difference() {
        union() {
            // Top plate of carrier
            translate([0, 0, base_height + gear_thickness + z_clearance * 2])
            difference() {
                cylinder(h=carrier_thickness, d=carrier_outer_dia, center=false);

                // Central hole for sun gear shaft
                translate([0, 0, -0.1])
                cylinder(h=carrier_thickness+0.2, d=8, center=false);
            }

            // Planet pins
            for (i = [0:num_planets-1]) {
                rotate([0, 0, i * 360/num_planets])
                translate([planet_orbit_radius, 0, base_height + z_clearance])
                cylinder(h=pin_height, d=pin_dia, center=false);
            }

            // Output shaft
            translate([0, 0, base_height + gear_thickness + z_clearance * 2 + carrier_thickness])
            cylinder(h=6, d=8, center=false);
        }

        // Hole in output shaft
        translate([0, 0, base_height + gear_thickness + z_clearance * 2 + carrier_thickness - 0.1])
        cylinder(h=6.2, d=4, center=false);
    }
}

// Ring gear (fixed to base)
module ring_gear_assembly() {
    // Base plate
    difference() {
        cylinder(h=base_height, d=ring_outer_radius*2, center=false);

        // Central bearing for sun gear
        translate([0, 0, -0.1])
        cylinder(h=base_height+0.2, d=8, center=false);
    }

    // Ring gear with internal teeth
    translate([0, 0, base_height + z_clearance])
    difference() {
        cylinder(h=gear_thickness, d=ring_outer_radius*2, center=false);

        // Internal gear teeth
        translate([0, 0, -0.1])
        involute_gear(ring_teeth, gear_thickness+0.2, 0, clearance, is_internal=true);

        // Viewing windows (optional, for debugging)
        for (i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([ring_pitch_dia/2 + 8, 0, -0.1])
            cylinder(h=gear_thickness+0.2, d=12, center=false);
        }
    }

    // Ring walls
    translate([0, 0, base_height + z_clearance])
    difference() {
        cylinder(h=ring_height - base_height - z_clearance, d=ring_outer_radius*2, center=false);
        translate([0, 0, -0.1])
        cylinder(h=ring_height - base_height - z_clearance + 0.2, d=ring_outer_radius*2 - 3, center=false);

        // Top opening for carrier shaft
        translate([0, 0, carrier_height])
        cylinder(h=ring_height, d=ring_outer_radius*2 - 8, center=false);
    }
}

// Complete assembly
module complete_gearbox() {
    // Fixed: Ring gear and base
    ring_gear_assembly();

    // Rotating: Sun gear
    sun_gear();

    // Rotating: Planet gears
    for (i = [0:num_planets-1]) {
        rotate([0, 0, i * 360/num_planets])
        translate([planet_orbit_radius, 0, base_height + z_clearance])
        planet_gear();
    }

    // Rotating: Planet carrier
    planet_carrier();
}

// Render the complete gearbox
complete_gearbox();
'}

{'content': '// Print-in-Place Planetary Gearbox
// Single stage with 3 planet gears
// Designed for PETG with 0.4mm nozzle, 0.1mm layer height

$fn = 80;

// Clearance for print-in-place (critical for PETG)
clearance = 0.35; // horizontal clearance between mating parts
z_clearance = 0.25; // vertical clearance

// Gear parameters
sun_teeth = 12;
planet_teeth = 12;
ring_teeth = sun_teeth + 2 * planet_teeth; // = 36
module_pitch = 2.5; // module (mm per tooth)

// Derived dimensions
sun_pitch_dia = sun_teeth * module_pitch;
planet_pitch_dia = planet_teeth * module_pitch;
ring_pitch_dia = ring_teeth * module_pitch;

// Gear geometry
gear_thickness = 6;
base_height = 2;
carrier_height = gear_thickness + base_height + z_clearance * 2;

// Planet carrier parameters
num_planets = 3;
planet_orbit_radius = (sun_pitch_dia + planet_pitch_dia) / 2;

// Ring gear dimensions
ring_inner_radius = ring_pitch_dia/2 + module_pitch * 1.5;
ring_outer_radius = ring_inner_radius + 5;
ring_wall_height = carrier_height + 8;

// Improved involute gear tooth profile
module spur_gear(teeth, thickness, bore_dia, clearance_adj=0) {
    pitch_radius = teeth * module_pitch / 2;
    addendum = module_pitch * 1.0;
    dedendum = module_pitch * 1.25;
    outer_radius = pitch_radius + addendum - clearance_adj/2;
    root_radius = pitch_radius - dedendum + clearance_adj/2;
    tooth_width = PI * module_pitch / 2;

    difference() {
        union() {
            // Root circle
            cylinder(h=thickness, r=root_radius, center=false);

            // Teeth
            for (i = [0:teeth-1]) {
                rotate([0, 0, i * 360/teeth])
                linear_extrude(height=thickness, convexity=10)
                polygon([
                    [0, 0],
                    [root_radius * cos(-tooth_width/(2*root_radius) * 180/PI), 
                     root_radius * sin(-tooth_width/(2*root_radius) * 180/PI)],
                    [outer_radius * cos(-tooth_width/(2.5*outer_radius) * 180/PI), 
                     outer_radius * sin(-tooth_width/(2.5*outer_radius) * 180/PI)],
                    [outer_radius * cos(tooth_width/(2.5*outer_radius) * 180/PI), 
                     outer_radius * sin(tooth_width/(2.5*outer_radius) * 180/PI)],
                    [root_radius * cos(tooth_width/(2*root_radius) * 180/PI), 
                     root_radius * sin(tooth_width/(2*root_radius) * 180/PI)]
                ]);
            }
        }

        // Bore
        if (bore_dia > 0) {
            translate([0, 0, -0.1])
            cylinder(h=thickness+0.2, d=bore_dia, center=false);
        }
    }
}

// Internal ring gear
module internal_ring_gear(teeth, thickness, inner_clearance=0) {
    pitch_radius = teeth * module_pitch / 2;
    addendum = module_pitch * 1.0;
    dedendum = module_pitch * 1.25;
    inner_radius = pitch_radius - addendum + inner_clearance/2;
    outer_radius = pitch_radius + dedendum;
    tooth_width = PI * module_pitch / 2;

    difference() {
        // Outer cylinder
        cylinder(h=thickness, r=outer_radius + 2, center=false);

        // Inner profile with teeth
        translate([0, 0, -0.1])
        union() {
            // Inner circle
            cylinder(h=thickness+0.2, r=inner_radius, center=false);

            // Tooth spaces
            for (i = [0:teeth-1]) {
                rotate([0, 0, i * 360/teeth])
                linear_extrude(height=thickness+0.2, convexity=10)
                polygon([
                    [0, 0],
                    [inner_radius * cos(-tooth_width/(2.2*inner_radius) * 180/PI), 
                     inner_radius * sin(-tooth_width/(2.2*inner_radius) * 180/PI)],
                    [outer_radius * cos(-tooth_width/(2.8*outer_radius) * 180/PI), 
                     outer_radius * sin(-tooth_width/(2.8*outer_radius) * 180/PI)],
                    [outer_radius * cos(tooth_width/(2.8*outer_radius) * 180/PI), 
                     outer_radius * sin(tooth_width/(2.8*outer_radius) * 180/PI)],
                    [inner_radius * cos(tooth_width/(2.2*inner_radius) * 180/PI), 
                     inner_radius * sin(tooth_width/(2.2*inner_radius) * 180/PI)]
                ]);
            }
        }
    }
}

// Sun gear (rotatable, driven)
module sun_gear() {
    sun_bore = 6;
    shaft_length = ring_wall_height - base_height - z_clearance - 2;

    translate([0, 0, base_height + z_clearance]) {
        // Gear
        spur_gear(sun_teeth, gear_thickness, sun_bore, clearance);

        // Drive shaft extending upward
        translate([0, 0, gear_thickness])
        difference() {
            cylinder(h=shaft_length - gear_thickness, d=sun_bore - clearance, center=false);
            // Hex socket for driving
            translate([0, 0, shaft_length - gear_thickness - 3])
            cylinder(h=3.1, d=3.5, $fn=6, center=false);
        }
    }
}

// Planet gear
module planet_gear() {
    planet_bore = 4.5 + clearance;
    spur_gear(planet_teeth, gear_thickness, planet_bore, clearance);
}

// Planet carrier (rotatable output)
module planet_carrier() {
    carrier_radius = planet_orbit_radius * 0.65;
    carrier_top_thickness = 3;
    pin_dia = 4.5 - clearance;
    pin_height = gear_thickness - z_clearance * 2;
    output_shaft_height = 8;

    translate([0, 0, base_height + z_clearance]) {
        // Planet pins (printed in place)
        for (i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets])
            translate([planet_orbit_radius, 0, 0])
            cylinder(h=pin_height, d=pin_dia, center=false);
        }

        // Top carrier plate
        translate([0, 0, gear_thickness + z_clearance])
        difference() {
            union() {
                // Main plate
                cylinder(h=carrier_top_thickness, r=carrier_radius, center=false);

                // Arms to planet pins
                for (i = [0:num_planets-1]) {
                    rotate([0, 0, i * 360/num_planets])
                    hull() {
                        cylinder(h=carrier_top_thickness, r=carrier_radius, center=false);
                        translate([planet_orbit_radius, 0, 0])
                        cylinder(h=carrier_top_thickness, d=pin_dia + 3, center=false);
                    }
                }

                // Output shaft
                translate([0, 0, carrier_top_thickness])
                cylinder(h=output_shaft_height, d=10, center=false);
            }

            // Sun gear shaft clearance
            translate([0, 0, -0.1])
            cylinder(h=carrier_top_thickness + 0.2, d=sun_teeth * module_pitch * 0.5, center=false);

            // Output shaft socket
            translate([0, 0, carrier_top_thickness + output_shaft_height - 4])
            cylinder(h=4.1, d=4, $fn=6, center=false);
        }
    }
}

// Ring gear assembly (fixed base)
module ring_gear_assembly() {
    // Base plate
    difference() {
        union() {
            cylinder(h=base_height, r=ring_outer_radius, center=false);

            // Feet for better bed adhesion
            for (i = [0:2]) {
                rotate([0, 0, i * 120])
                translate([ring_outer_radius - 2, 0, 0])
                cylinder(h=base_height, d=8, center=false);
            }
        }

        // Central bearing hole for sun gear
        translate([0, 0, -0.1])
        cylinder(h=base_height+0.2, d=7 + clearance, center=false);
    }

    // Ring gear with internal teeth
    translate([0, 0, base_height + z_clearance])
    difference() {
        internal_ring_gear(ring_teeth, gear_thickness, clearance);

        // Viewing windows for inspection
        for (i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([ring_outer_radius - 1, 0, -0.1])
            cylinder(h=gear_thickness+0.2, d=10, center=false);
        }
    }

    // Ring walls
    translate([0, 0, base_height + z_clearance])
    difference() {
        cylinder(h=ring_wall_height - base_height - z_clearance, r=ring_outer_radius, center=false);

        // Inner cavity
        translate([0, 0, -0.1])
        cylinder(h=ring_wall_height - base_height - z_clearance + 0.2, r=ring_outer_radius - 3, center=false);

        // Top opening for carrier output shaft
        translate([0, 0, carrier_height - base_height])
        cylinder(h=ring_wall_height, r=ring_outer_radius - 6, center=false);

        // Side viewing windows
        for (i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([ring_outer_radius - 1.5, 0, gear_thickness + 1])
            cylinder(h=8, d=10, center=false);
        }
    }
}

// Complete assembly
module complete_gearbox() {
    // Fixed: Ring gear and base
    ring_gear_assembly();

    // Rotating: Sun gear
    sun_gear();

    // Rotating: Planet gears
    for (i = [0:num_planets-1]) {
        rotate([0, 0, i * 360/num_planets])
        translate([planet_orbit_radius, 0, base_height + z_clearance])
        planet_gear();
    }

    // Rotating: Planet carrier
    planet_carrier();
}

// Render the complete gearbox
complete_gearbox();
'}

{'content': '// Print-in-Place Planetary Gearbox
// Single stage with 3 planet gears
// Designed for PETG with 0.4mm nozzle, 0.1mm layer height

$fn = 100;

// Clearance for print-in-place (optimized for PETG)
clearance = 0.4; // horizontal clearance between mating parts
z_clearance = 0.3; // vertical clearance (3 layers at 0.1mm)

// Gear parameters - chosen for proper meshing
sun_teeth = 12;
planet_teeth = 15;
ring_teeth = sun_teeth + 2 * planet_teeth; // = 42
module_pitch = 2.0; // module (mm per tooth)

// Derived dimensions
sun_pitch_dia = sun_teeth * module_pitch;
planet_pitch_dia = planet_teeth * module_pitch;
ring_pitch_dia = ring_teeth * module_pitch;

// Gear geometry
gear_thickness = 8;
base_height = 2.5;

// Planet carrier parameters
num_planets = 3;
planet_orbit_radius = (sun_pitch_dia + planet_pitch_dia) / 2;

// Ring gear dimensions
ring_inner_radius = ring_pitch_dia/2 + module_pitch * 1.4;
ring_outer_radius = ring_inner_radius + 4;

// Involute gear tooth using polygon approximation
module involute_tooth(pitch_radius, addendum, dedendum, tooth_angle) {
    outer_radius = pitch_radius + addendum;
    root_radius = pitch_radius - dedendum;

    // Simplified tooth profile
    tooth_thickness_angle = tooth_angle * 0.45;

    polygon([
        [root_radius * cos(-tooth_thickness_angle), 
         root_radius * sin(-tooth_thickness_angle)],
        [pitch_radius * cos(-tooth_thickness_angle * 0.8), 
         pitch_radius * sin(-tooth_thickness_angle * 0.8)],
        [outer_radius * cos(-tooth_thickness_angle * 0.6), 
         outer_radius * sin(-tooth_thickness_angle * 0.6)],
        [outer_radius * cos(tooth_thickness_angle * 0.6), 
         outer_radius * sin(tooth_thickness_angle * 0.6)],
        [pitch_radius * cos(tooth_thickness_angle * 0.8), 
         pitch_radius * sin(tooth_thickness_angle * 0.8)],
        [root_radius * cos(tooth_thickness_angle), 
         root_radius * sin(tooth_thickness_angle)]
    ]);
}

// External spur gear
module spur_gear(teeth, thickness, bore_dia, backlash=0) {
    pitch_radius = teeth * module_pitch / 2;
    addendum = module_pitch * 1.0;
    dedendum = module_pitch * 1.25;
    tooth_angle = 360 / teeth;

    difference() {
        union() {
            // Base cylinder at root
            cylinder(h=thickness, r=pitch_radius - dedendum + backlash/2, center=false);

            // Teeth
            for (i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                linear_extrude(height=thickness, convexity=10, scale=0.95)
                involute_tooth(pitch_radius - backlash/2, addendum - backlash/2, 
                              dedendum - backlash/2, tooth_angle);
            }
        }

        // Bore
        if (bore_dia > 0) {
            translate([0, 0, -0.1])
            cylinder(h=thickness+0.2, d=bore_dia, center=false);
        }
    }
}

// Internal ring gear
module internal_ring_gear(teeth, thickness, backlash=0) {
    pitch_radius = teeth * module_pitch / 2;
    addendum = module_pitch * 1.0;
    dedendum = module_pitch * 1.25;
    tooth_angle = 360 / teeth;
    inner_radius = pitch_radius - addendum + backlash/2;
    outer_radius = pitch_radius + dedendum + 2;

    difference() {
        // Outer cylinder
        cylinder(h=thickness, r=outer_radius, center=false);

        // Inner space with tooth pockets
        translate([0, 0, -0.1])
        union() {
            cylinder(h=thickness+0.2, r=inner_radius, center=false);

            // Tooth pockets
            for (i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                linear_extrude(height=thickness+0.2, convexity=10)
                polygon([
                    [inner_radius * cos(-tooth_angle * 0.47), 
                     inner_radius * sin(-tooth_angle * 0.47)],
                    [pitch_radius * cos(-tooth_angle * 0.42), 
                     pitch_radius * sin(-tooth_angle * 0.42)],
                    [outer_radius * cos(-tooth_angle * 0.35), 
                     outer_radius * sin(-tooth_angle * 0.35)],
                    [outer_radius * cos(tooth_angle * 0.35), 
                     outer_radius * sin(tooth_angle * 0.35)],
                    [pitch_radius * cos(tooth_angle * 0.42), 
                     pitch_radius * sin(tooth_angle * 0.42)],
                    [inner_radius * cos(tooth_angle * 0.47), 
                     inner_radius * sin(tooth_angle * 0.47)]
                ]);
            }
        }
    }
}

// Sun gear with integrated shaft
module sun_gear() {
    sun_bore = 5;
    shaft_dia = sun_bore - clearance;
    shaft_height = 20;

    translate([0, 0, base_height + z_clearance]) {
        // Main gear
        spur_gear(sun_teeth, gear_thickness, sun_bore, clearance);

        // Extended shaft for driving
        translate([0, 0, gear_thickness])
        difference() {
            cylinder(h=shaft_height - gear_thickness, d=shaft_dia, center=false);
            // Hex drive socket
            translate([0, 0, shaft_height - gear_thickness - 4])
            cylinder(h=4.1, d=3.2, $fn=6, center=false);
        }
    }
}

// Single planet gear
module planet_gear() {
    planet_bore = 4 + clearance;
    spur_gear(planet_teeth, gear_thickness, planet_bore, clearance);
}

// Planet carrier with pins and output
module planet_carrier() {
    pin_dia = 4 - clearance;
    pin_height = gear_thickness - z_clearance;
    carrier_thickness = 3;
    carrier_radius = planet_orbit_radius * 0.6;
    output_height = 10;

    translate([0, 0, base_height + z_clearance]) {
        // Planet pins (capture planets)
        for (i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets])
            translate([planet_orbit_radius, 0, 0])
            cylinder(h=pin_height, d=pin_dia, center=false, $fn=30);
        }

        // Top carrier plate
        translate([0, 0, gear_thickness + z_clearance])
        difference() {
            union() {
                // Central hub
                cylinder(h=carrier_thickness, r=carrier_radius, center=false);

                // Arms to planets
                for (i = [0:num_planets-1]) {
                    rotate([0, 0, i * 360/num_planets])
                    hull() {
                        translate([carrier_radius * 0.3, 0, 0])
                        cylinder(h=carrier_thickness, r=3, center=false);
                        translate([planet_orbit_radius, 0, 0])
                        cylinder(h=carrier_thickness, d=pin_dia + 2.5, center=false);
                    }
                }

                // Output shaft
                translate([0, 0, carrier_thickness])
                difference() {
                    cylinder(h=output_height, d=11, center=false);
                    // Taper for better bridging
                    translate([0, 0, output_height - 2])
                    cylinder(h=2.1, d1=11, d2=12, center=false);
                }
            }

            // Clearance for sun shaft
            translate([0, 0, -0.1])
            cylinder(h=carrier_thickness + output_height + 0.2, d=6, center=false);

            // Output hex socket
            translate([0, 0, carrier_thickness + output_height - 5])
            cylinder(h=5.1, d=4.5, $fn=6, center=false);
        }
    }
}

// Base and ring gear housing
module ring_gear_assembly() {
    wall_thickness = 3;
    total_height = 25;

    // Base plate
    difference() {
        union() {
            cylinder(h=base_height, r=ring_outer_radius, center=false);

            // Corner feet for stability
            for (i = [0:2]) {
                rotate([0, 0, i * 120])
                translate([ring_outer_radius * 0.8, 0, 0])
                cylinder(h=base_height, d=6, center=false);
            }
        }

        // Sun gear bearing
        translate([0, 0, -0.1])
        cylinder(h=base_height+0.2, d=6 + clearance, center=false);
    }

    // Internal ring gear
    translate([0, 0, base_height + z_clearance])
    difference() {
        internal_ring_gear(ring_teeth, gear_thickness, clearance);

        // Inspection windows
        for (i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([ring_outer_radius - 2, 0, -0.1])
            cylinder(h=gear_thickness+0.2, d=8, center=false);
        }
    }

    // Outer walls
    translate([0, 0, base_height + z_clearance]) {
        difference() {
            // Outer shell
            cylinder(h=total_height - base_height - z_clearance, r=ring_outer_radius, center=false);

            // Inner cavity
            translate([0, 0, -0.1])
            cylinder(h=total_height - base_height - z_clearance + 0.2, 
                    r=ring_outer_radius - wall_thickness, center=false);

            // Top opening for carrier shaft
            translate([0, 0, gear_thickness + z_clearance + 5])
            cylinder(h=total_height, r=ring_outer_radius - wall_thickness - 3, center=false);

            // Side windows for viewing mechanism
            for (i = [0:2]) {
                rotate([0, 0, i * 120 + 60])
                translate([ring_outer_radius - 1.5, 0, gear_thickness + 2])
                cylinder(h=10, d=8, center=false);
            }
        }
    }
}

// Complete print-in-place assembly
module complete_gearbox() {
    ring_gear_assembly();  // Fixed
    sun_gear();            // Rotates

    // Three planet gears
    for (i = [0:num_planets-1]) {
        rotate([0, 0, i * 360/num_planets])
        translate([planet_orbit_radius, 0, base_height + z_clearance])
        planet_gear();
    }

    planet_carrier();      // Rotates (output)
}

complete_gearbox();
